export function getHairFileUrl(styleId: string): string {
  if (!styleId || styleId === 'none') return '';
  let style = HAIRSTYLES_CATALOG.find(h => h.id === styleId || h.id.includes(styleId) || styleId.includes(h.id));
  if (!style && HAIRSTYLES_CATALOG.length > 1) {
    style = HAIRSTYLES_CATALOG[1]; // Fallback to first available hairstyle
  }
  return style ? style.url : '';
}
